'use strict';
// Cosmetic particles use a separate clock and hash, never the world's random seed.
const powerPalette={meteor:'#ffb068',lightning:'#c4eaff',fire:'#ff8f50',rain:'#89d8ff',heal:'#8ef0b0',bless:'#ffe7a0',champion:'#ffd568',harvest:'#b7ed7a',temple:'#e6ccff',cleanse:'#b1ffff',curse:'#bb8aff',plague:'#b3dc5f',erase:'#d6e4ff'};
const powerDurations={meteor:1.65,lightning:.85,fire:1.05,rain:1.4,heal:1.3,bless:1.4,champion:1.6,harvest:1.35,temple:1.5,cleanse:1.3,curse:1.4,plague:1.5,erase:1.1};
let powerClock=0,powerFrameLast=performance.now(),powerSequence=0;
const powerOld={effect,frame:runSmoothFrame};
function effectAnimationTime(){return powerClock;}
function powerHash(seed,n){const a=Math.sin(seed*12.9898+n*78.233)*43758.5453;return a-Math.floor(a);}
function powerPhase(fx){const age=Math.max(0,fx.max-fx.life),impact=fx.type==='meteor'?.38:fx.type==='lightning'?.08:.18;return{age,impact,progress:Math.max(0,Math.min(1,(age-impact)/(fx.max-impact))),arrival:Math.min(1,age/impact)};}
effect=function(type,x,y,r){if(!Object.hasOwn(powerPalette,type)){powerOld.effect(type,x,y,r);return;}const nearby=[...visualEffects.values()].some(f=>f.type===type&&powerClock-f.born<.10&&Math.hypot(f.x-x,f.y-y)<Math.max(.6,r*.4));if(nearby)return;powerOld.effect(type,x,y,r);const fx=effects.at(-1);if(!fx)return;fx.life=fx.max=powerDurations[type];fx.seed=++powerSequence;visualEffects.set(fx,{...fx,born:powerClock});while(visualEffects.size>48)visualEffects.delete(visualEffects.keys().next().value);};
runSmoothFrame=function(now){const dt=Math.max(0,Math.min(.12,(now-powerFrameLast)/1000));powerFrameLast=now;if(!document.querySelector('dialog[open]'))powerClock+=dt;powerOld.frame(now);};
function powerRing(x,y,r,color,alpha,width=.13){ctx.globalAlpha=Math.max(0,alpha);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.ellipse(x,y,r,r*.72,0,0,Math.PI*2);ctx.stroke();}
function powerGlow(x,y,r,color,alpha){ctx.globalAlpha=Math.max(0,alpha);const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,color);g.addColorStop(1,color+'00');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2);}
function powerStar(x,y,size,color,alpha){ctx.globalAlpha=Math.max(0,alpha);ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(x,y-size);ctx.lineTo(x+size*.25,y-size*.25);ctx.lineTo(x+size,y);ctx.lineTo(x+size*.25,y+size*.25);ctx.lineTo(x,y+size);ctx.lineTo(x-size*.25,y+size*.25);ctx.lineTo(x-size,y);ctx.lineTo(x-size*.25,y-size*.25);ctx.closePath();ctx.fill();}
function paintPowerEffect(fx){const {age,impact,progress:p,arrival}=powerPhase(fx),color=powerPalette[fx.type]||'#fff4c4',r=Math.max(.8,fx.r),seed=fx.seed||Math.floor(fx.x*13+fx.y*7),fade=1-p,travel=1-Math.pow(1-p,3);ctx.save();ctx.lineCap='round';ctx.lineJoin='round';
// A short ground cue makes the exact landing point legible at any zoom.
if(age<impact)powerRing(fx.x,fx.y,r*.5,color,(1-arrival)*.65,.10);
if(fx.type==='meteor'){
if(arrival<1){const drop=1-arrival*arrival,x=fx.x-6*drop,y=fx.y-12*drop;ctx.strokeStyle='#ffb96f';ctx.lineWidth=.55;ctx.globalAlpha=.8;ctx.beginPath();ctx.moveTo(x-3.8,y-7);ctx.lineTo(x,y);ctx.stroke();powerGlow(x,y,2.4,color,.65);drawSprite(13,x,y,3.5);}
else{powerGlow(fx.x,fx.y,r*1.4,color,Math.pow(fade,3)*.65);powerRing(fx.x,fx.y,.4+travel*r*1.25,'#ffdc9c',fade*.9,.22);powerRing(fx.x,fx.y,.2+travel*r*.85,color,fade*.5,.12);for(let i=0;i<22;i++){const a=powerHash(seed,i)*Math.PI*2,d=(.3+powerHash(seed,i+35)*r)*travel;ctx.globalAlpha=fade*fade;ctx.fillStyle=i%3?'#ffbf78':'#fff1bc';ctx.beginPath();ctx.arc(fx.x+Math.cos(a)*d,fx.y+Math.sin(a)*d*.72-Math.sin(p*Math.PI)*1.5,.07+powerHash(seed,i+70)*.13,0,7);ctx.fill();}}}
else if(fx.type==='lightning'){
if(age<.32){ctx.globalAlpha=Math.max(0,1-age/.32);ctx.strokeStyle=color;ctx.lineWidth=.35;ctx.beginPath();ctx.moveTo(fx.x+.8,fx.y-10);ctx.lineTo(fx.x-.7,fx.y-6);ctx.lineTo(fx.x+.6,fx.y-5.8);ctx.lineTo(fx.x-.8,fx.y-2.2);ctx.lineTo(fx.x+.3,fx.y-2.4);ctx.lineTo(fx.x,fx.y);ctx.stroke();ctx.strokeStyle='#ffffff';ctx.lineWidth=.12;ctx.stroke();ctx.lineWidth=.10;ctx.beginPath();ctx.moveTo(fx.x-.6,fx.y-5.8);ctx.lineTo(fx.x-2,fx.y-4.7);ctx.lineTo(fx.x-1.6,fx.y-3.5);ctx.stroke();}if(age>=impact){powerGlow(fx.x,fx.y,r+1,color,Math.pow(fade,3)*.75);powerRing(fx.x,fx.y,.2+travel*r,color,fade*.8);for(let i=0;i<10;i++){const a=i*Math.PI/5;powerStar(fx.x+Math.cos(a)*travel*r,fx.y+Math.sin(a)*travel*r*.7,.15*fade,'#fff',fade);}}}
else if(fx.type==='rain'){
powerRing(fx.x,fx.y,r*.85,color,fade*.25,.08);ctx.strokeStyle=color;ctx.lineWidth=.09;for(let i=0;i<24;i++){const offset=powerHash(seed,i),t=(age*1.5+offset)%1,a=powerHash(seed,i+24)*Math.PI*2,d=Math.sqrt(powerHash(seed,i+48))*r,x=fx.x+Math.cos(a)*d,y=fx.y+Math.sin(a)*d*.7;ctx.globalAlpha=Math.min(1,age*5)*Math.min(1,(fx.life)*3)*.75;ctx.beginPath();ctx.moveTo(x-.2,y-3*(1-t));ctx.lineTo(x,y-3*(1-t)+.55);ctx.stroke();if(t>.83)powerRing(x,y,.1+(t-.83)*1.8,color,(1-t)*2,.06);}}
else if(fx.type==='fire'){
powerGlow(fx.x,fx.y,r,color,fade*.3);for(let i=0;i<18;i++){const a=powerHash(seed,i)*Math.PI*2,d=Math.sqrt(powerHash(seed,i+20))*r*.8,t=(p+powerHash(seed,i+40)*.35)%1;ctx.globalAlpha=fade*(1-t);ctx.fillStyle=i%3?'#ffa35c':'#fff1a1';ctx.beginPath();ctx.ellipse(fx.x+Math.cos(a)*d,fx.y+Math.sin(a)*d*.7-t*2,.12*(1-t)+.05,.3*(1-t)+.08,-.2,0,7);ctx.fill();}}
else{
const dark=['curse','plague','erase'].includes(fx.type);powerGlow(fx.x,fx.y,r*1.1,color,fade*.16);powerRing(fx.x,fx.y,dark?r*(1-p*.75):.3+travel*r,color,fade*.75);for(let i=0;i<18;i++){const a=powerHash(seed,i)*Math.PI*2+(dark?p*2:0),d=Math.sqrt(powerHash(seed,i+18))*r*(dark?1-p*.5:.35+travel*.65),x=fx.x+Math.cos(a)*d,y=fx.y+Math.sin(a)*d*.7-p*1.7,alpha=Math.sin(Math.PI*Math.min(1,age/fx.max))*.8;if(dark){ctx.globalAlpha=alpha;ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,.07+powerHash(seed,i+40)*.10,0,7);ctx.fill();}else powerStar(x,y,.09+powerHash(seed,i+40)*.13,color,alpha);}if(['bless','champion','temple'].includes(fx.type)){ctx.globalAlpha=fade*.3;ctx.fillStyle=color;ctx.fillRect(fx.x-.35,fx.y-7*(1-p*.4),.7,7*(1-p*.4));powerStar(fx.x,fx.y-1.3,fx.type==='champion'?.65:.4,color,fade);}if(['heal','cleanse'].includes(fx.type)){ctx.globalAlpha=fade;ctx.fillStyle=color;ctx.fillRect(fx.x-.12,fx.y-1.5,.24,.85);ctx.fillRect(fx.x-.42,fx.y-1.2,.84,.24);}}
ctx.restore();}
